import { configureStore } from '@reduxjs/toolkit';
import { persistStore, persistReducer, FLUSH, REHYDRATE, PAUSE, PERSIST, PURGE, REGISTER } from 'redux-persist';
import storage from 'redux-persist/lib/storage';

import { authReducer } from 'store';
import recipeReducer from './recipe/reducer';
import weatherReducer from './weather/reducer';
import currencyReducer from './currency/reducer';
import filesReducer from './files/reducer';
import rootReducer from './root/reducer';
import timerReducer from './timer/reducer';
import { timeManagementReducer } from './timemanagement';

const persistConfig = {
  key: 'root',
  storage,
};
const persistConfigRecipe = {
  key: 'recipe',
  storage,
};
const persistConfigFiles = {
  key: 'files',
  storage,
};
const persistConfigWeather = {
  key: 'weather',
  storage,
  version: 2,
  migrate: async state => {
    if (!state) return undefined;
    // Old persisted weather slice may have nested `weather` key
    // e.g. { weather: { weatherToday: {...}, weatherWeek: {...}, ... } }
    // New reducer expects flat keys: { weatherToday: {...}, weatherWeek: {...}, ..., cache: {} }
    let weather = state;
    if (state.weather && typeof state.weather === 'object') {
      weather = { ...state.weather };
    }
    if (!weather.cache) weather.cache = {};
    return weather;
  },
};
const persistConfigCurrency = {
  key: 'currency',
  storage,
};
const persistConfigTimer = {
  key: 'timer',
  storage,
};
const persistConfigAuth = {
  key: 'auth',
  storage,
  whitelist: ['token'],
};

const persistedRootReducer = persistReducer(persistConfig, rootReducer);
const persistedAuthReducer = persistReducer(persistConfigAuth, authReducer);
const persistedRecipeReducer = persistReducer(persistConfigRecipe, recipeReducer);
const persistedRecipeFiles = persistReducer(persistConfigFiles, filesReducer);
const persistedWeather = persistReducer(persistConfigWeather, weatherReducer);
const persistedCurrency = persistReducer(persistConfigCurrency, currencyReducer);
const persistedTimer = persistReducer(persistConfigTimer, timerReducer);

// timemanagement НЕ персистим — единый источник истины — сервер (иначе расхождение между устройствами)
// ранее был persist с key 'timemanagement', оставлял stale данные в localStorage
const nonPersistedTimeManagement = timeManagementReducer;

const store = configureStore({
  reducer: {
    root: persistedRootReducer,
    recipe: persistedRecipeReducer,
    files: persistedRecipeFiles,
    auth: persistedAuthReducer,
    weather: persistedWeather,
    currency: persistedCurrency,
    timer: persistedTimer,
    timemanagement: nonPersistedTimeManagement,
  },
  middleware: getDefaultMiddleware =>
    getDefaultMiddleware({
      serializableCheck: {
        ignoredActions: [FLUSH, REHYDRATE, PAUSE, PERSIST, PURGE, REGISTER],
      },
    }),
});

export const persistor = persistStore(store);

// очистка старого persist для timemanagement (был причиной расхождения между устройствами)
try {
  if (typeof window !== 'undefined' && window.localStorage) {
    localStorage.removeItem('persist:timemanagement');
  }
} catch {}

export default store;